select count(1)
from property_detailed a
where a.status in ('MAKE_USE_OF','LEAVE_UNUSED','WEED_OUT','REPAIR_REPORT')
and a.authority='DEPOSITORY'

    and a.start_time between #{date.startTime} and #{date.endTime}


    and a.status ='REPAIR_REPORT'




            and a.usage_date <= #{usageDate}


            and a.usage_date between #{date.startTime} and #{date.endTime}






            and a.maintenance_date <= #{usageDate}


            and a.maintenance_date between #{date.startTime} and #{date.endTime}
